-- Function: public.sp_provision_platform_organization
-- Backup generated on 2026-10-25 20:34:04

CREATE OR REPLACE PROCEDURE public.sp_provision_platform_organization(IN p_org_id uuid, IN p_name character varying, IN p_location character varying, IN p_admin_email character varying, IN p_branch_count integer DEFAULT 1)  LANGUAGE plpgsql AS $procedure$ DECLARE     v_raw_slug VARCHAR;     v_slug VARCHAR;     v_slug_count INT;     v_existing_user_id UUID;     v_existing_tenant_id UUID;     v_admin_user_id UUID;     v_derived_name VARCHAR;     v_branches_to_create INT;     v_i INT;     v_branch_id UUID;     v_branch_name VARCHAR;     v_branch_loc VARCHAR;     v_role_id UUID; BEGIN     v_raw_slug := trim(both '-' from regexp_replace(lower(p_name), '[^a-z0-9]+', '-', 'g'));     IF v_raw_slug IS NULL OR v_raw_slug = '' THEN         v_slug := 'org-' || substring(p_org_id::text, 1, 8);     ELSE         v_slug := v_raw_slug;     END IF;      SELECT COUNT(1) INTO v_slug_count FROM tenants WHERE slug = v_slug;     IF v_slug_count > 0 THEN         v_slug := v_slug || '-' || substring(p_org_id::text, 1, 4);     END IF;      INSERT INTO tenants (id, name, slug)      VALUES (p_org_id, p_name, v_slug)      ON CONFLICT (id) DO NOTHING;      SELECT id, tenant_id INTO v_existing_user_id, v_existing_tenant_id      FROM users      WHERE LOWER(email) = LOWER(trim(p_admin_email)) OR normalized_email = UPPER(trim(p_admin_email))      LIMIT 1;      IF v_existing_user_id IS NOT NULL THEN         v_admin_user_id := v_existing_user_id;         IF v_existing_tenant_id = '10000000-0000-0000-0000-000000000001'::uuid THEN             UPDATE users SET tenant_id = p_org_id WHERE id = v_admin_user_id;         END IF;     ELSE         v_admin_user_id := gen_random_uuid();         v_derived_name := initcap(split_part(split_part(trim(p_admin_email), '@', 1), '.', 1));         IF v_derived_name IS NULL OR v_derived_name = '' THEN             v_derived_name := 'Daycare Director';         END IF;          INSERT INTO users (id, tenant_id, email, normalized_email, email_confirmed, first_name, last_name, display_name, is_active)         VALUES (v_admin_user_id, p_org_id, trim(p_admin_email), UPPER(trim(p_admin_email)), TRUE, 'Admin', v_derived_name, v_derived_name, TRUE)         ON CONFLICT (normalized_email) DO NOTHING;     END IF;      INSERT INTO organizations (id, tenant_id, name, location, is_active)     VALUES (p_org_id, p_org_id, p_name, p_location, TRUE)     ON CONFLICT (id) DO NOTHING;      v_branches_to_create := GREATEST(1, p_branch_count);     FOR v_i IN 1..v_branches_to_create LOOP         v_branch_id := gen_random_uuid();         IF v_i = 1 THEN             v_branch_name := 'Main Campus';         ELSIF v_i = 2 THEN             v_branch_name := 'Annex Campus';         ELSE             v_branch_name := 'Campus ' || v_i;         END IF;          IF p_location IS NOT NULL AND trim(p_location) <> '' THEN             v_branch_loc := p_location;         ELSE             v_branch_loc := 'Main Branch';         END IF;          INSERT INTO branches (id, tenant_id, organization_id, name, location, is_active)         VALUES (v_branch_id, p_org_id, p_org_id, v_branch_name, v_branch_loc, TRUE)         ON CONFLICT (id) DO NOTHING;     END LOOP;      IF v_admin_user_id IS NOT NULL THEN         INSERT INTO organization_memberships (user_id, organization_id, tenant_id, status)         VALUES (v_admin_user_id, p_org_id, p_org_id, 'Active')         ON CONFLICT (user_id, organization_id) DO NOTHING;          SELECT id INTO v_role_id          FROM roles          WHERE name IN ('OrganizationAdmin', 'OrganizationOwner')            AND (tenant_id = p_org_id OR tenant_id IS NULL)          ORDER BY tenant_id NULLS LAST          LIMIT 1;          IF v_role_id IS NOT NULL THEN             INSERT INTO user_organization_roles (user_id, role_id, organization_id, tenant_id)             VALUES (v_admin_user_id, v_role_id, p_org_id, p_org_id)             ON CONFLICT (user_id, role_id, organization_id) DO NOTHING;         END IF;     END IF; END; $procedure$ ;
